import sys

import os

import re

import json

import requests

from bs4 import BeautifulSoup

import html2text

def clean_filename(title):

    &quot;&quot;&quot;清理文件名中的非法字符&quot;&quot;&quot;

    return re.sub(r&#39;[\\/:*?&quot;&amp;lt;&amp;gt;|]&#39;, &#39;_&#39;, title).strip()

def clean_html_content(content_soup):

    &quot;&quot;&quot;

    清理正文中的广告、公众号卡片、赞赏区，并根据关键字切断文末推送内容

    &quot;&quot;&quot;

    # 1. 移除微信/知乎常见的标准广告与名片组件

    unwanted_selectors = [

        &#39;.js_ad_area&#39;, &#39;#js_ad_area&#39;,  # 微信底部广告

        &#39;#js_profile_qrcode&#39;, &#39;.qr_code_pc&#39;,  # 微信二维码

        &#39;mp-common-profile&#39;, &#39;.mp-common-profile&#39;,  # 微信公众号名片卡片

        &#39;.rich_media_tool&#39;, &#39;#js_to_user_profile&#39;,  # 关注/阅读原文工具栏

        &#39;.reward_area&#39;, &#39;#js_reward_area&#39;,  # 赞赏区域

        &#39;.rich_media_area_extra&#39;,  # 微信底部推荐区

        &#39;[class*=&quot;Card&quot;]&#39;, &#39;[class*=&quot;McnLink&quot;]&#39;,  # 知乎/微信营销卡片

        &#39;[class*=&quot;LinkCard&quot;]&#39;

    ]

    for selector in unwanted_selectors:

        for tag in content_soup.select(selector):

            tag.decompose()

    # 2. 尾部截断机制：遇到以下关键字时，直接斩断该节点及其后面的所有 DOM 节点

    cutoff_keywords = [

        &#39;搜索公众号添加&#39;,

        &#39;扫码关注&#39;,

        &#39;往期推荐&#39;,

        &#39;推荐阅读&#39;,

        &#39;往期精彩&#39;,

        &#39;长按识别二维码&#39;,

        &#39;送礼物&#39;,

        &#39;发布于&#39;

    ]

    for tag in content_soup.find_all([&#39;p&#39;, &#39;section&#39;, &#39;div&#39;, &#39;h2&#39;, &#39;h3&#39;, &#39;span&#39;, &#39;strong&#39;]):

        text = tag.get_text(strip=True)

        # 判断节点文本较短（避免误删大容器）且包含截断关键字

        if len(text) &amp;lt; 100 and any(kw in text for kw in cutoff_keywords):

            print(f&quot;检测到尾部推送标记 [{text[:15]}...]，正在切断后续所有内容...&quot;)

            # 获取该节点之后的所有 HTML 元素并彻底删除

            next_elements = list(tag.find_all_next())

            for elem in next_elements:

                elem.decompose()

            # 删除当前节点本身

            tag.decompose()

            break

    # 3. 清理残余的二维码图片（通过 URL 特征过滤）

    for img in content_soup.find_all(&#39;img&#39;):

        src = (img.get(&#39;data-src&#39;) or img.get(&#39;src&#39;) or &#39;&#39;).lower()

        if any(k in src for k in [&#39;qrcode&#39;, &#39;qr_code&#39;]):

            img.decompose()

    return content_soup

def download_and_process_images(content_soup, safe_title, base_dir, headers):

    &quot;&quot;&quot;

    下载文章中的所有图片，保存到 notes/文件夹A/文件夹A 子文件夹中，

    并修改 HTML 中的引用路径为相对路径

    &quot;&quot;&quot;

    img_dir = os.path.join(base_dir, safe_title)

    os.makedirs(img_dir, exist_ok=True)

    img_tags = content_soup.find_all(&#39;img&#39;)

    img_count = 0

    for img in img_tags:

        img_url = img.get(&#39;data-src&#39;) or img.get(&#39;src&#39;) or img.get(&#39;data-original&#39;)

        if not img_url or not img_url.startswith(&#39;http&#39;):

            continue

        img_count += 1

        img_filename = f&quot;img_{img_count:02d}.png&quot;

        img_save_path = os.path.join(img_dir, img_filename)

        try:

            print(f&quot;正在下载图片 [{img_count}]: {img_url}&quot;)

            img_resp = requests.get(img_url, headers=headers, timeout=15)

            if img_resp.status_code == 200:

                with open(img_save_path, &#39;wb&#39;) as f:

                    f.write(img_resp.content)

                # 更新 Markdown 内引用的相对路径

                relative_path = f&quot;{safe_title}/{img_filename}&quot;

                img[&#39;src&#39;] = relative_path

                # 清理多余属性

                for attr in [&#39;data-src&#39;, &#39;data-original&#39;, &#39;srcset&#39;, &#39;style&#39;]:

                    if attr in img.attrs:

                        del img.attrs[attr]

            else:

                print(f&quot;图片下载失败 (HTTP {img_resp.status_code}): {img_url}&quot;)

        except Exception as e:

            print(f&quot;下载图片发生异常: {e}&quot;)

    return content_soup

def parse_zhihu(soup, url):

    &quot;&quot;&quot;专门针对知乎专栏/回答的解析器&quot;&quot;&quot;

    author = &quot;Unknown&quot;

    content_html = &quot;&quot;

    script_tag = soup.find(&#39;script&#39;, id=&#39;js-initialData&#39;)

    if script_tag and script_tag.string:

        try:

            data = json.loads(script_tag.string)

            article_id = url.split(&#39;/&#39;)[-1].split(&#39;?&#39;)[0]

            articles = data.get(&#39;initialState&#39;, {}).get(&#39;entities&#39;, {}).get(&#39;articles&#39;, {})

            if article_id in articles:

                art = articles[article_id]

                author = art.get(&#39;author&#39;, {}).get(&#39;name&#39;, author)

                content_html = art.get(&#39;content&#39;, &#39;&#39;)

                print(&quot;Successfully parsed Zhihu article via initialData JSON!&quot;)

        except Exception as e:

            print(f&quot;JSON parse fallback failed: {e}&quot;)

    if not content_html:

        author_node = soup.find(&#39;meta&#39;, {&#39;itemprop&#39;: &#39;name&#39;}) or soup.find(&#39;div&#39;, class_=&#39;AuthorInfo-name&#39;)

        if author_node:

            author = author_node.get(&#39;content&#39;) or author_node.get_text(strip=True)

        content_node = soup.find(&#39;div&#39;, class_=&#39;Post-RichTextContainer&#39;) or \

                       soup.find(&#39;div&#39;, class_=&#39;RichText&#39;) or \

                       soup.find(&#39;article&#39;)

        if content_node:

            content_html = str(content_node)

    return author, content_html

def parse_article(url, custom_title):

    headers = {

        &#39;User-Agent&#39;: &#39;Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1&#39;,

        &#39;Accept&#39;: &#39;text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8&#39;,

        &#39;Accept-Language&#39;: &#39;zh-CN,zh-Hans;q=0.9&#39;,

    }

    print(f&quot;Requesting: {url}&quot;)

    response = requests.get(url, headers=headers, timeout=15)

    print(f&quot;Response Status Code: {response.status_code}&quot;)

    if response.status_code != 200:

        print(f&quot;Error: HTTP {response.status_code} returned by target site.&quot;)

        sys.exit(1)

    response.encoding = &#39;utf-8&#39;

    soup = BeautifulSoup(response.text, &#39;html.parser&#39;)

    author = &quot;Unknown&quot;

    content_html = &quot;&quot;

    if &quot;zhihu.com&quot; in url:

        author, content_html = parse_zhihu(soup, url)

    elif &quot;mp.weixin.qq.com&quot; in url:

        author_node = soup.find(&#39;a&#39;, id=&#39;js_name&#39;) or soup.find(&#39;span&#39;, class_=&#39;profile_meta_value&#39;)

        if author_node:

            author = author_node.get_text(strip=True)

        content_node = soup.find(&#39;div&#39;, class_=&#39;rich_media_content&#39;) or soup.find(&#39;div&#39;, id=&#39;js_content&#39;)

        if content_node:

            content_html = str(content_node)

    else:

        content_node = soup.find(&#39;article&#39;) or soup.find(&#39;main&#39;)

        content_html = str(content_node) if content_node else &quot;&quot;

    if not content_html:

        print(f&quot;Error: Could not extract content HTML from {url}&quot;)

        sys.exit(1)

    safe_title = clean_filename(custom_title)

    base_dir = os.path.join(&quot;notes&quot;, safe_title)

    os.makedirs(base_dir, exist_ok=True)

    # 1. 解析 DOM

    content_soup = BeautifulSoup(content_html, &#39;html.parser&#39;)

    # 2. 执行【尾部截断与净化】（在此步就会彻底砍掉“搜索添加公众号”及之后的所有内容）

    content_soup = clean_html_content(content_soup)

    # 3. 下载保留下来的正文图片（广告与引流图因已被删除，不会被下载）

    content_soup = download_and_process_images(content_soup, safe_title, base_dir, headers)

    # 4. HTML 转 Markdown

    h = html2text.HTML2Text()

    h.ignore_links = False

    h.ignore_images = False

    h.body_width = 0

    markdown_body = h.handle(str(content_soup))

    markdown_content = f&quot;&quot;&quot;---

title: &quot;{custom_title}&quot;

author: &quot;{author}&quot;

source_url: &quot;{url}&quot;

---

# {custom_title}

&amp;gt; **作者:** {author}  

&amp;gt; **原文链接:** [{url}]({url})

---

{markdown_body}

&quot;&quot;&quot;

    return safe_title, base_dir, markdown_content

def main():

    if len(sys.argv) &amp;lt; 3:

        print(&quot;Usage: python fetch_wechat.py &amp;lt;url&amp;gt; &amp;lt;custom_title&amp;gt;&quot;)

        sys.exit(1)

    url = sys.argv[1]

    custom_title = sys.argv[2]

    safe_title, base_dir, md_content = parse_article(url, custom_title)

    filepath = os.path.join(base_dir, f&quot;{safe_title}.md&quot;)

    with open(filepath, &#39;w&#39;, encoding=&#39;utf-8&#39;) as f:

        f.write(md_content)

    print(f&quot;\n成功完成！Markdown 文件已保存至: {filepath}&quot;)

if __name__ == &quot;__main__&quot;:

    main()

